let started=false;
export function startModel(){if(started)return;started=true;const canvas=document.getElementById('model');const gl=canvas.getContext('webgl');if(!gl){const p=document.createElement('p');p.textContent='3D display needs WebGL. Try a browser with hardware acceleration.';canvas.replaceWith(p);return;}
const vs=`attribute vec3 p;attribute vec3 n;uniform float yaw;uniform float pitch;uniform float aspect;varying float light;void main(){mat3 ry=mat3(cos(yaw),0.,-sin(yaw),0.,1.,0.,sin(yaw),0.,cos(yaw));mat3 rx=mat3(1.,0.,0.,0.,cos(pitch),sin(pitch),0.,-sin(pitch),cos(pitch));vec3 v=rx*ry*p;vec3 nn=rx*ry*n;float z=7.-v.z;gl_Position=vec4(v.x*2.6/aspect,v.y*2.6,(z-4.)*.15,z);light=.35+.65*max(dot(nn,normalize(vec3(.3,.8,1.))),0.);}`;
const fs=`precision mediump float;uniform vec3 color;varying float light;void main(){gl_FragColor=vec4(color*light,1.);}`;
const shader=(type,src)=>{const s=gl.createShader(type);gl.shaderSource(s,src);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(s));return s;};const program=gl.createProgram();gl.attachShader(program,shader(gl.VERTEX_SHADER,vs));gl.attachShader(program,shader(gl.FRAGMENT_SHADER,fs));gl.linkProgram(program);if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw Error('3D shader failed');gl.useProgram(program);
const loc={p:gl.getAttribLocation(program,'p'),n:gl.getAttribLocation(program,'n'),yaw:gl.getUniformLocation(program,'yaw'),pitch:gl.getUniformLocation(program,'pitch'),aspect:gl.getUniformLocation(program,'aspect'),color:gl.getUniformLocation(program,'color')};let yaw=.55,pitch=-.35,separated=false,drag=false,lastX=0,lastY=0;
function cylinder(a,b,r){const data=[],dir=b.map((v,i)=>v-a[i]),length=Math.hypot(...dir),axis=dir.map(v=>v/length);let u=Math.abs(axis[1])>.9?[1,0,0]:[0,1,0];const cross=(x,y)=>[x[1]*y[2]-x[2]*y[1],x[2]*y[0]-x[0]*y[2],x[0]*y[1]-x[1]*y[0]];u=cross(axis,u);const ul=Math.hypot(...u);u=u.map(v=>v/ul);const v=cross(axis,u);const point=(c,t)=>c.map((x,i)=>x+r*(u[i]*Math.cos(t)+v[i]*Math.sin(t)));const normal=t=>u.map((x,i)=>x*Math.cos(t)+v[i]*Math.sin(t));for(let i=0;i<32;i++){const t=i*Math.PI/16,s=(i+1)*Math.PI/16;for(const [c,q]of[[a,t],[b,t],[b,s],[a,t],[b,s],[a,s]])data.push(...point(c,q),...normal(q));}return new Float32Array(data);}
const buffer=gl.createBuffer();function mesh(a,b,r,color){const data=cylinder(a,b,r);gl.bindBuffer(gl.ARRAY_BUFFER,buffer);gl.bufferData(gl.ARRAY_BUFFER,data,gl.DYNAMIC_DRAW);gl.enableVertexAttribArray(loc.p);gl.enableVertexAttribArray(loc.n);gl.vertexAttribPointer(loc.p,3,gl.FLOAT,false,24,0);gl.vertexAttribPointer(loc.n,3,gl.FLOAT,false,24,12);gl.uniform3fv(loc.color,color);gl.drawArrays(gl.TRIANGLES,0,data.length/6);}
function draw(){const dpr=Math.min(devicePixelRatio||1,2);canvas.width=canvas.clientWidth*dpr;canvas.height=canvas.clientHeight*dpr;gl.viewport(0,0,canvas.width,canvas.height);gl.enable(gl.DEPTH_TEST);gl.clearColor(.065,.16,.21,1);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);gl.uniform1f(loc.yaw,yaw);gl.uniform1f(loc.pitch,pitch);gl.uniform1f(loc.aspect,canvas.width/canvas.height);const c=[.8,.48,.26],f=[.12,.74,.76],s=separated?.4:0;
mesh([-2.6-s,0,0],[-.28-s,0,0],.16,c);mesh([.28+s,0,0],[2.6+s,0,0],.16,c);mesh([0,.3+s,0],[0,1.8+s,0],.16,c);mesh([-.33,0,0],[.33,0,0],.25,f);mesh([0,0,0],[0,.4,0],.25,f);
// A curved tube makes the elbow visible as a separate fitting.
for(let i=0;i<20;i++){const a=i*Math.PI/40,b=(i+1)*Math.PI/40;mesh([2.6+s+.55*Math.sin(a),-.55+.55*Math.cos(a),0],[2.6+s+.55*Math.sin(b),-.55+.55*Math.cos(b),0],.22,[.53,.66,.77]);}mesh([3.15+s,-.55,0],[3.15+s,-1.6,0],.16,c);}
canvas.onpointerdown=e=>{drag=true;lastX=e.clientX;lastY=e.clientY;canvas.setPointerCapture(e.pointerId);};canvas.onpointermove=e=>{if(!drag)return;yaw+=(e.clientX-lastX)*.009;pitch=Math.max(-1.3,Math.min(1.3,pitch+(e.clientY-lastY)*.009));lastX=e.clientX;lastY=e.clientY;draw();};canvas.onpointerup=canvas.onpointercancel=()=>drag=false;canvas.onkeydown=e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();yaw+=e.key==='ArrowLeft'?-.15:e.key==='ArrowRight'?.15:0;pitch+=e.key==='ArrowUp'?-.1:e.key==='ArrowDown'?.1:0;draw();}};
document.getElementById('rotate-left').onclick=()=>{yaw-=.25;draw();};document.getElementById('rotate-right').onclick=()=>{yaw+=.25;draw();};document.getElementById('explode').onclick=e=>{separated=!separated;e.target.textContent=separated?'Assemble parts':'Separate parts';draw();};document.getElementById('reset-model').onclick=()=>{yaw=.55;pitch=-.35;separated=false;document.getElementById('explode').textContent='Separate parts';draw();};new ResizeObserver(draw).observe(canvas);draw();}
